<script setup lang="ts">
import {computed,ref,watch,nextTick,onUnmounted} from 'vue';import {cards,sources,type Card} from './cards';import {draw,spreads,parseHistory,storageKey,type Reading,type Spread} from './engine';
import {saveReading,clearSavedHistory,exportSavedHistory} from './historyStore';
import ArcanaIcon from './ArcanaIcon.vue';
import CardArtwork from './CardArtwork.vue';
import {matchesCardSearch} from './cardSearch';
import {candidateArt,artStatus,artNote,installedArtCount} from './art';
import {auditFor,auditLang,reviewLabel,modernPrompt,modernReversalNote,batch} from './audit';
import {translate,type Locale} from './i18n';import {cardEnglish} from './cardEnglish';import {buildAIContext} from './ai';import ReflectionChat from './ReflectionChat.vue';import RealAcceptanceChat from './RealAcceptanceChat.vue';
const navIcons={reading:'draw',library:'cards',history:'history',about:'book'} as const;
const locale=ref<Locale>('zh');try{locale.value=localStorage.getItem('glass-arcana:locale')==='en'?'en':'zh';}catch{}
const t=(text:string)=>translate(text,locale.value);
watch(locale,value=>{document.documentElement.lang=value==='en'?'en':'zh-CN';document.title=value==='en'?'Glass Arcana':'琉璃秘典 · Glass Arcana';try{localStorage.setItem('glass-arcana:locale',value);}catch{}},{immediate:true});
const cardName=(c:Card)=>locale.value==='en'?c.english:c.name;
const cardText=(c:Card,key:'theme'|'symbol'|'prompt')=>{const a=auditFor(c.id);if(a){const l=auditLang(locale.value);return key==='theme'?a.modern.theme[l]:key==='symbol'?a.iconography.textChecked[l]:a.modern.uprightPrompt[l];}return locale.value==='en'?cardEnglish[c.id][key]:c[key];};
const tab=ref('reading'),spread=ref<Spread>('three'),question=ref(''),reversals=ref(true),current=ref<Reading|null>(null),history=ref<Reading[]>([]),notice=ref(''),search=ref(''),filter=ref('全部'),selected=ref<Card|null>(null);
try{history.value=parseHistory(localStorage.getItem(storageKey));}catch{notice.value='浏览器存储不可用，本次仍可抽牌，但无法保存历史。';}
let previousFocus:HTMLElement|null=null;
watch(selected,async value=>{if(value){previousFocus=document.activeElement as HTMLElement;await nextTick();document.querySelector<HTMLButtonElement>('.modal .close')?.focus();}else{previousFocus?.focus();}});
function modalKeys(event:KeyboardEvent){if(!selected.value)return;if(event.key==='Escape'){selected.value=null;return;}if(event.key==='Tab'){const items=Array.from(document.querySelectorAll<HTMLElement>('.modal button,.modal a[href],.modal summary'));if(!items.length)return;const first=items[0],last=items[items.length-1];if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}}}
document.addEventListener('keydown',modalKeys);onUnmounted(()=>document.removeEventListener('keydown',modalKeys));
const filtered=computed(()=>cards.filter(c=>(filter.value==='全部'||c.suit===filter.value)&&matchesCardSearch(c,search.value)));
const card=(id:string)=>cards.find(c=>c.id===id)!;
const concealed=ref<string[]>([]);
async function reveal(id:string){const index=current.value?.draws.findIndex(d=>d.id===id)??-1;concealed.value=concealed.value.filter(x=>x!==id);await nextTick();document.querySelectorAll<HTMLButtonElement>('.drawn .face')[index]?.focus();}
function openReading(r:Reading){concealed.value=[];current.value=r;tab.value='reading';}

function begin(){if(current.value)return;try{const reading:Reading={version:1,id:crypto.randomUUID(),createdAt:new Date().toISOString(),question:question.value.trim(),spread:spread.value,draws:draw(spread.value,reversals.value)};concealed.value=reading.draws.map(d=>d.id);current.value=reading;const saved=saveReading(reading,history.value,()=>localStorage);history.value=saved.records;notice.value=saved.saved?'已保存到此浏览器。':'已完成抽牌，但浏览器存储已满或不可用，未能保存。';}catch{notice.value='安全随机源不可用。请通过 localhost 或 HTTPS 打开，不会用不安全抽牌替代。';}}
function exportHistory(){const url=URL.createObjectURL(new Blob([exportSavedHistory(history.value)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='glass-arcana-history.json';a.click();URL.revokeObjectURL(url);}
function clearHistory(){if(!confirm(t('清除这个浏览器内的全部解读记录？建议先导出备份。')))return;if(clearSavedHistory(()=>localStorage)){history.value=[];notice.value='本地历史已清除。';}else{notice.value='无法清除浏览器存储，请检查浏览器权限。';}}
function interpretation(d:Reading['draws'][number]){const c=card(d.id);const a=auditFor(d.id);if(a)return `${t(d.position)} · ${a.modern.theme[auditLang(locale.value)]}. ${modernPrompt(d.id,d.reversed,locale.value)} ${modernReversalNote(d.id,d.reversed,locale.value)}`;return locale.value==='zh'?`${d.position} · ${c.theme}。${d.reversed?'逆位作为反思视角：留意受阻、过度或内在表现，不等于坏事。':'正位作为反思视角：观察主题如何出现，不保证某个结果。'} ${c.prompt}`:`${t(d.position)} · ${cardText(c,'theme')}. ${d.reversed?'A reversed card invites reflection on blocked, excessive or inward expressions; it does not mean something bad.':'An upright card invites you to observe this theme in your experience, without guaranteeing an outcome.'} ${cardText(c,'prompt')}`;}
const aiContext=computed(()=>current.value?buildAIContext(current.value,locale.value):null);
</script>
<template>
<div class="shell"><header><a class="brand" href="#" @click.prevent="tab='reading'"><span class="sigil">✦</span><span>{{t("琉璃秘典")}}<small>GLASS ARCANA</small></span></a><nav :aria-label="t('主导航')"><button v-for="[id,label] in [['reading','静心抽牌'],['library','78 张牌'],['history','我的记录'],['about','关于与来源']]" :class="{active:tab===id}" @click="tab=id"><ArcanaIcon :name="navIcons[id as keyof typeof navIcons]" :size="20" /><span>{{t(label)}}</span></button></nav><button class="language" @click="locale=locale==='zh'?'en':'zh'" :aria-label="locale==='zh'?'Switch to English':'切换到中文'"><ArcanaIcon name="language" :size="20" /><span>{{locale==='zh'?'EN':'中文'}}</span></button></header>
<main><template v-if="tab==='reading'"><section v-if="!current" class="hero"><h1>{{locale==='en'?'A place to read the cards.':'抽一组牌，留一份记录。'}}</h1><p>{{locale==='en'?'Rider–Waite–Smith tarot. Draw, compare the imagery, and write down what matters to you.':'韦特–史密斯塔罗。抽牌、查阅图像与原典，记录自己的理解。'}}</p></section>
<div v-if="!current" class="ritual"><div class="ritual-copy"><h2>{{locale==='en'?'Your reading':'这一次，想看什么？'}}</h2><p>{{t("牌面不是预言。它是观察经验、梳理想法的一种语言。")}}</p><label for="question">{{t("此刻，你想探索什么？")}} <span>{{t("可留空")}}</span></label><textarea id="question" v-model="question" maxlength="500" :placeholder="t('例如：我可以如何更好地面对这次变化？')"></textarea><fieldset><legend>{{t("选择牌阵")}}</legend><button v-for="(positions,id) in spreads" :class="{chosen:spread===id}" :aria-pressed="spread===id" @click="spread=id">{{t(id==='one'?'单张 · 此刻':'三张 · 探索')}}<small>{{positions.map(t).join(' / ')}}</small></button></fieldset><label class="check"><input type="checkbox" v-model="reversals">{{t("纳入逆位视角")}} <span>{{t("不是好坏判断")}}</span></label><button class="primary" @click="begin"><ArcanaIcon name="shuffle" :size="20" />{{t("洗牌 · 开始探索")}}</button></div><figure class="deck-display"><div class="home-card-back" role="img" :aria-label="locale==='en'?'Card back study':'牌背习作'"><img src="/art/card-back.svg" alt="" width="1024" height="1536"></div><figcaption><strong>{{locale==='en'?'Your cards are waiting':'等待你的牌'}}</strong><span>{{locale==='en'?'Draw once, then reveal each card. Stained-glass back candidate.':'抽牌后，逐张点击翻开。彩绘玻璃牌背候选。'}}</span></figcaption></figure></div>
<section v-else class="results"><div class="result-head"><div><h2>{{current.question||t('与此刻的自己对话')}}</h2><p>{{t("结果已固定。以下为项目原创反思文案，并非原典引文或未来预测。")}}</p></div></div><div class="draw-grid" :class="{single:current.draws.length===1}"><article v-for="d in current.draws" :key="d.id" class="drawn"><span class="position">{{t(d.position)}}</span><button class="face equal-face" :class="{revealed:!concealed.includes(d.id)}" @click="concealed.includes(d.id)?reveal(d.id):selected=card(d.id)" :aria-label="concealed.includes(d.id)?(locale==='en'?'Reveal card: ':'翻开牌：')+t(d.position):(locale==='en'?'View card: ':'查看牌：')+cardName(card(d.id))"><img v-if="concealed.includes(d.id)" src="/art/card-back.svg" alt="" width="1024" height="1536"><CardArtwork :locale="locale" v-else :id="d.id" :alt="cardName(card(d.id))" class="candidate-draw" :class="{reverse:d.reversed}" /></button><div class="card-caption"><template v-if="!concealed.includes(d.id)"><small>{{artStatus(d.id,locale)}}</small><h3>{{cardName(card(d.id))}}</h3><span class="orientation">{{t(d.reversed?'逆位 · 内在视角':'正位 · 显现视角')}}</span><p>{{interpretation(d)}}</p></template><span v-else>{{locale==='en'?'Click to reveal':'点击翻牌'}}</span></div></article></div><ReflectionChat v-if="aiContext && !concealed.length" :context="aiContext" /><RealAcceptanceChat v-if="aiContext && !concealed.length" :context="aiContext" /><div class="reading-end"><button @click="current=null">{{locale==='en'?'Finish this reading':'结束本次解读'}}</button></div></section></template>
<section v-if="tab==='library'"><div class="page-title"><h1>{{t("78 个意象，一部图谱。")}}</h1><p>{{t("22 张大阿卡纳 · 56 张小阿卡纳。身份完整，图像与知识逐牌核校中。")}}</p></div><p class="audit-coverage">{{locale==='en'?'Primary texts: 78 basic named-card sections first-pass checked. Additional historical meanings, comprehensive image comparisons and final artwork approval remain pending; card-specific targeted checks do not constitute full audit.':'原典文本：78 张基础条目首轮核对；额外历史释义、图版全面对照与成品图终审仍待完成；逐牌专项检查不等于全面核校通过。'}}</p><div class="filters"><input v-model="search" :aria-label="t('搜索牌名')" :placeholder="t('搜索牌名、英文或主题…')"><select v-model="filter" :aria-label="t('筛选花色')"><option v-for="s in ['全部','大阿卡纳','权杖','圣杯','宝剑','星币']" :value="s">{{t(s)}}</option></select><span>{{filtered.length}} {{locale==='en'?(filtered.length===1?'card':'cards'):'张'}}</span></div><div class="library-grid"><button class="mini-card" v-for="c in filtered" :key="c.id" @click="selected=c"><span>{{c.arcana==='major'?String(c.rank).padStart(2,'0'):t(c.suit)}}</span><CardArtwork :locale="locale" v-if="candidateArt[c.id]" :id="c.id" sizes="(max-width: 600px) 38vw, 140px" :alt="cardName(c)" loading="lazy" class="candidate-thumb" /><i v-else>✧</i><small v-if="candidateArt[c.id]">{{artStatus(c.id,locale)}}</small><strong>{{cardName(c)}}</strong><small v-if="locale==='zh'">{{c.english}}</small><small v-if="!candidateArt[c.id] && artNote(c.id,locale)">{{artStatus(c.id,locale)}}</small><em>{{cardText(c,'theme')}}</em></button></div><p v-if="!filtered.length">{{t("没有找到匹配的牌。")}}</p></section>
<section v-if="tab==='history'"><div class="page-title"><h1>{{t("留下片刻的思考。")}}</h1><p>{{t("只保存在当前浏览器，最多 50 条。不上传，不追踪。清除浏览器数据会丢失记录。")}}</p></div><div class="actions"><button @click="exportHistory" :disabled="!history.length"><ArcanaIcon name="export" :size="20" />{{t("导出 JSON 备份")}}</button><button @click="clearHistory" :disabled="!history.length">{{t("清除本地记录")}}</button></div><p v-if="!history.length" class="empty">{{t("还没有记录。你的第一段对话，随时可以开始。")}}</p><button v-for="r in history" class="history-item" @click="openReading(r)"><small>{{new Date(r.createdAt).toLocaleString(locale==='en'?'en-US':'zh-CN')}}</small><strong>{{r.question||t('与此刻的自己对话')}}</strong><span>{{r.draws.map(d=>cardName(card(d.id))+(d.reversed?(locale==='en'?' (reversed)':'（逆）'):'')).join(' · ')}} ↗</span></button></section>
<section v-if="tab==='about'" class="about"><div class="page-title"><h1>{{t("关于这部秘典")}}</h1></div><p class="audit-coverage">{{locale==='en'?'Primary texts: 78 basic named-card sections first-pass checked. Additional historical meanings, comprehensive image comparisons and final artwork approval remain pending; card-specific targeted checks do not constitute full audit.':'原典文本：78 张基础条目首轮核对；额外历史释义、图版全面对照与成品图终审仍待完成；逐牌专项检查不等于全面核校通过。'}}</p><h2>{{t("一个体系，不混搭。")}}</h2><p>{{t("采用 Rider–Waite–Smith 78 张身份结构。力量为 VIII，正义为 XI。牌阵由程序固定位置；使用浏览器安全随机源，无放回抽取；每张牌独立决定正逆位。没有模型替你挑牌。基础功能无需 API；可选 OpenAI 对话需要单独启用服务并确认数据分享，可能产生费用。")}}</p><h2>{{t("知识与来源分层")}}</h2><p>{{t("牌名与结构、可观察符号、历史解释、现代反思分别记录。78 张基础原典条目完成选择性首轮核对，额外历史释义尚待审。早期图版全面对照与成品图终审仍待完成，专项检查范围另见逐牌说明。现代正逆位反思是项目原创，不冒充 Waite 的历史占卜词条，也不是完整原典译本。")}}</p><article v-for="s in sources"><a :href="s.url" target="_blank" rel="noopener noreferrer">{{t(s.title)}} ↗</a><p>{{t(s.note)}}</p></article><h2>{{t("原创视觉，透明进度")}}</h2><p>{{t("方向为哥特彩绘玻璃。当前有 78 张候选图（含命运轮专项复核后的改编候选），无占位，没有最终定稿牌面；界面几何装饰不是正式牌图。78 张牌的符号、人物与花色数量必须逐张验证。当前原创 SVG 牌背采用 180° 旋转对称结构，仍为候选设计。")}}</p><h2>{{t("免费、无广告、无追踪")}}</h2><p>{{t("无会员、支付、广告或遥测。历史仅保存在本机浏览器；可选 OpenAI 对话只在明确同意后发送当前牌阵、问题和对话。代码采用 MIT；原创文案、图标和牌图采用相应 CC BY 4.0 条款，仅涵盖实际持有的可授权权利；第三方资料保留各自权利。这不保证生成图独占或无侵权风险。此前有效授予的 CC0 权利继续有效，详见 CONTENT-LICENSE.md。")}}</p><h2>{{t("使用边界")}}</h2><p>{{t("仅供文化学习和自我反思，不预测命运、不推断他人隐私，也不替代医疗、法律或财务建议。「死神」等名称不可用于推断真实死亡或疾病。遇到现实问题，请依据事实与适当的专业支持作出决定。")}}</p></section>
<p v-if="notice" role="status" class="notice">{{t(notice)}}</p></main><footer><span>✦ {{t('琉璃秘典')}} / GLASS ARCANA</span><span>{{t("文化 · 意象 · 自我反思")}}</span><span>STUDY TOOL · 0.1.0</span></footer></div>
<div v-if="selected" class="modal" @click.self="selected=null" @keydown.esc="selected=null"><section role="dialog" aria-modal="true" :aria-label="cardName(selected)" tabindex="-1"><button class="close" autofocus @click="selected=null"><ArcanaIcon name="close" :size="20" />{{locale==='en'?'Close':'关闭'}}</button><span class="section-no">{{selected.id}} · {{reviewLabel(selected.id,locale)}}</span><h2>{{cardName(selected)}}</h2><figure v-if="candidateArt[selected.id]" class="candidate-figure"><CardArtwork :locale="locale" :id="selected.id" :alt="cardName(selected)" /><figcaption>{{locale==='en'?'Generated candidate artwork. Visual/rights review pending; not approved.':'生成候选图，视觉及权利核验待完成，非定稿。'}}</figcaption><p v-if="selected.id==='major-2'">{{locale==='en'?'B/J/TORA and partial scroll concealment passed targeted visual review; final artwork review remains pending.':'B/J/TORA 与卷轴遮挡专项复核通过；整体成品仍待最终审校。'}}</p></figure><p v-if="artNote(selected.id,locale)">{{artStatus(selected.id,locale)}} · {{artNote(selected.id,locale)}}</p><p>{{selected.english}} · {{cardText(selected,'theme')}}</p><h3>{{locale==='en'?'Historical image description · not an exact reproduction of this artwork':'原典图像描述 · 不代表本项目牌面逐项复刻'}}</h3><p>{{cardText(selected,'symbol')}}</p><section v-if="auditFor(selected.id)?.iconography.pendingChecks.length" class="pending-checks"><h3>{{locale==='en'?'Pending checks and differences':'待核事项与差异说明'}}</h3><ul><li v-for="(check,index) in auditFor(selected.id)!.iconography.pendingChecks" :key="index">{{check[auditLang(locale)]}}</li></ul></section><p v-if="selected.arcana==='minor' && selected.rank<=10 && selected.count!==null">{{t('主花色器物目标数量：')}}{{selected.count}}{{t('。宫廷牌数字不是器物数量。')}}</p><div class="audit-state"><p>{{reviewLabel(selected.id,locale)}}</p><p>{{locale==='en'?'Comprehensive early-plate review: incomplete · Final artwork approval: pending':'早期图版全面核验：未完成 · 项目成品图终审：待完成'}}</p></div><details v-if="auditFor(selected.id)" class="historical"><summary>{{locale==='en'?'Historical study notes · not a prediction':'历史资料学习区 · 不作为预测'}}</summary><p>{{locale==='en'?'Selective summaries, not a complete translation. Sources: A. E. Waite, Wikisource transcription of the 1922 edition; original illustration attribution: Pamela Colman Smith.':'选择性历史摘要，不是完整译本。来源：A. E. Waite，Wikisource 的 1922 年版转录；原插图署名 Pamela Colman Smith。'}}</p><h3>{{locale==='en'?'Historical symbolism':'历史象征说明'}}</h3><p>{{auditFor(selected.id)!.historical.symbolism[auditLang(locale)]}}</p><h3>{{locale==='en'?'Historical divinatory terms':'历史占卜词条'}}</h3><p>{{auditFor(selected.id)!.historical.divination[auditLang(locale)]}}</p><p>{{auditFor(selected.id)!.historical.locator}}</p><p>{{auditFor(selected.id)!.limitations[auditLang(locale)]}}</p><ul><li v-for="source in batch.sources.filter(s=>auditFor(selected!.id)!.sources.includes(s.id))"><a :href="source.url" target="_blank" rel="noopener noreferrer">{{source.id}} ↗</a><small>{{source.edition}}</small></li></ul></details><h3>{{t("反思问题 · 项目原创")}}</h3><p>{{cardText(selected,'prompt')}}</p><h3>{{t("来源与状态")}}</h3><p>{{t("本条为学习摘要，待对照原典与早期图像逐项核校。不是原文引文。")}}</p><a :href="sources[0].url" target="_blank" rel="noopener">{{t("查看原典核校入口 ↗")}}</a></section></div>
</template>
